-- Descripciones de monturas de la tienda (inglés del servidor -> español).
-- Las familias con el mismo texto y distinto nombre se resuelven con patrones.
local ES = StoreES
local patterns = ES.linePatterns

local function N(name) return ES.name(name) end

local function add(pattern, fn)
    table.insert(patterns, { pattern, fn })
end

add("^Ride an? (.+) on your way through ancient chambers and tombs and have a loyal friend by your side while fighting countless mummies and other creatures%.$", function(n)
    return "Cabalga sobre " .. N(n) .. " por antiguas cámaras y tumbas y ten a tu lado a un amigo leal mientras combates contra incontables momias y otras criaturas."
end)

add("^Treat your character to a new travelling companion with a gentle nature and an impressive antler: The noble (.+) will carry you through the deepest snow%.$", function(n)
    return "Regala a tu personaje un nuevo compañero de viaje de carácter dócil y con una cornamenta impresionante: el noble " .. N(n) .. " te llevará a través de la nieve más profunda."
end)

add("^The (.+) is the perfect mount for those who are too busy to take care of an animal mount or simply like to travel on a beautiful, magic hand%-woven carpet%.$", function(n)
    return N(n) .. " es la montura perfecta para quienes están demasiado ocupados para cuidar de un animal o que simplemente disfrutan viajando sobre una hermosa alfombra mágica tejida a mano."
end)

add("^Thousands of years ago, its ancestors ruled the world%. Only recently, it found its way into Tibia%. The (.+) likes to hide in dense wood and overturned trees%.$", function(n)
    return "Hace miles de años, sus antepasados gobernaban el mundo. Hace poco llegó a Tibia. Al " .. N(n) .. " le gusta esconderse en bosques densos y bajo árboles caídos."
end)

add("^Thousands of years ago, its ancestors ruled the world%. Only recently, it found its way into Tibia%. The (.+) feels most comfortable in torrential rivers and behind dangerous waterfalls%.$", function(n)
    return "Hace miles de años, sus antepasados gobernaban el mundo. Hace poco llegó a Tibia. El " .. N(n) .. " se siente más a gusto en ríos torrenciales y tras cascadas peligrosas."
end)

add("^Thousands of years ago, its ancestors ruled the world%. Only recently, it found its way into Tibia%. The (.+) has been spotted in a sea of flames and fire deep down in the depths of Kazordoon%.$", function(n)
    return "Hace miles de años, sus antepasados gobernaban el mundo. Hace poco llegó a Tibia. El " .. N(n) .. " ha sido avistado en un mar de llamas y fuego en lo más profundo de Kazordoon."
end)

add("^Waccoons are cuddly creatures that love nothing more than to be petted and snuggled! Share a hug, ruffle the fur of the (.+) and scratch it behind its ears to make it happy%.$", function(n)
    return "¡Los waccoons son criaturas tiernas que no desean nada más que mimos y caricias! Comparte un abrazo, acaricia el pelaje del " .. N(n) .. " y ráscale detrás de las orejas para hacerlo feliz."
end)

add("^You are fascinated by insectoid creatures and can picture yourself riding one during combat or just for travelling%? The (.+) will carry you through the Tibian wilderness with ease%.$", function(n)
    return "¿Te fascinan las criaturas insectoides y te imaginas montando una en combate o simplemente de viaje? " .. N(n) .. " te llevará con facilidad por los parajes salvajes de Tibia."
end)

add("^With its thick, shaggy hair, the (.+) will keep you warm even in the chilly climate of the Ice Islands%. Due to its calm and peaceful nature, it is not letting itself getting worked up easily%.$", function(n)
    return "Con su espeso y desgreñado pelaje, el " .. N(n) .. " te mantendrá caliente incluso en el gélido clima de las Islas de Hielo. Gracias a su carácter tranquilo y pacífico, no se altera con facilidad."
end)

add("^The (.+) is out searching for the best bamboo in Tibia%. Its heavy armour allows it to visit even the most dangerous places%. Treat it nicely with its favourite food from time to time and it will become a loyal partner%.$", function(n)
    return N(n) .. " anda buscando el mejor bambú de Tibia. Su pesada armadura le permite visitar incluso los lugares más peligrosos. Trátalo bien con su comida favorita de vez en cuando y se convertirá en un compañero leal."
end)

add("^If you are more of an imp than an angel, you may prefer riding out on an? (.+) to scare fellow Tibians on their festive strolls%. Its devilish mask, claw%-like hands and sharp hooves makes it the perfect companion for any daring adventurer who likes to stand out%.$", function(n)
    return "Si eres más diablillo que ángel, quizá prefieras salir a cabalgar sobre " .. N(n) .. " para asustar a otros tibianos en sus paseos festivos. Su máscara diabólica, sus manos como garras y sus afilados cascos lo convierten en el compañero perfecto para cualquier aventurero audaz que quiera destacar."
end)

add("^Incredible strength and smartness, an irrepressible will to survive, passionately hunting in groups%. If these attributes apply to your character, we have found the perfect partner for you%. Have a proper look at (.+), which stands loyally by its master's side in every situation%. It is time to become the leader of the wolf pack!$", function(n)
    return "Fuerza e inteligencia increíbles, una voluntad de sobrevivir irreprimible y pasión por cazar en grupo. Si estos atributos describen a tu personaje, hemos encontrado a tu compañero perfecto. Echa un buen vistazo a " .. N(n) .. ", que permanece fielmente junto a su amo en cualquier situación. ¡Es hora de convertirte en el líder de la manada!"
end)

add("^Rumour has it that many years ago elder witches had gathered to hold a magical feast high up in the mountains%. They had crossbred (.+) to easily conquer rocky canyons and deep valleys%. Nobody knows what happened on their way up but only the mount has been seen ever since%.$", function(n)
    return "Cuenta el rumor que hace muchos años unas brujas ancianas se reunieron para celebrar un festín mágico en lo alto de las montañas. Habían cruzado a " .. N(n) .. " para conquistar con facilidad cañones rocosos y valles profundos. Nadie sabe qué ocurrió durante su ascenso, pero desde entonces solo se ha visto a la montura."
end)

add("^For centuries, humans and monsters have dumped their garbage in the swamps around Venore%. The combination of old, rusty weapons, stale mana and broken runes have turned some of the swamp dwellers into gigantic frogs%. Benefit from those mutations and make the (.+) a faithful mount for your adventures even beyond the bounds of the swamp%.$", function(n)
    return "Durante siglos, humanos y monstruos han arrojado su basura a los pantanos de Venore. La mezcla de armas oxidadas, maná rancio y runas rotas ha convertido a algunos habitantes del pantano en ranas gigantescas. Aprovecha esas mutaciones y haz de " .. N(n) .. " una montura fiel para tus aventuras, incluso más allá de los límites del pantano."
end)

add("^It is said that in ancient times, the sabre%-tooth tiger was already used as a mount by elder warriors of Svargrond%. As seafaring began to expand, this noble big cat was also transported to other regions in Tibia%. Influenced by the new environment and climatic changes, the fur of the (.+) has developed its extraordinary colouring over several generations%.$", function(n)
    return "Se dice que ya en la antigüedad los guerreros ancianos de Svargrond usaban el tigre diente de sable como montura. Cuando la navegación se expandió, este noble felino también fue llevado a otras regiones de Tibia. Influido por el nuevo entorno y los cambios climáticos, el pelaje del " .. N(n) .. " desarrolló su extraordinaria coloración a lo largo de varias generaciones."
end)

add("^It is said that the (.+) was born long before Banor walked the earth of Tibia%. While its parents died in the war against the cruel hordes sent by Brog and Zathroth, their child survived by hiding in skulls of burned enemies%. It never left its hiding spot and as it grew older, the skulls merged into its body%. Now, it is fully%-grown and thirsts for revenge%.$", function(n)
    return "Se dice que " .. N(n) .. " nació mucho antes de que Banor pisara la tierra de Tibia. Mientras sus padres morían en la guerra contra las crueles hordas enviadas por Brog y Zathroth, su cría sobrevivió escondiéndose en cráneos de enemigos quemados. Nunca abandonó su escondite y, al crecer, los cráneos se fundieron con su cuerpo. Ahora es adulta y sedienta de venganza."
end)

add("^When the nights are getting longer and freezing wind brings driving snow into the land, snowmen rise and shine on every corner%. Lately, a peaceful, arcane creature has found shelter in one of them and used its magical power to call the (.+) into being%. Wrap yourself up well and warmly and jump on the back of your new frosty companion%.$", function(n)
    return "Cuando las noches se alargan y el viento helado trae nieve a la tierra, los muñecos de nieve surgen y brillan en cada esquina. Hace poco, una criatura pacífica y arcana se refugió en uno de ellos y usó su poder mágico para dar vida a " .. N(n) .. ". Abrígate bien y salta a lomos de tu nuevo y gélido compañero."
end)

add("^Once a majestic and proud warhorse, the (.+) has fallen in a horrible battle many years ago%. Driven by agony and pain, its spirit once again took possession of its rotten corpse to avenge its death%. Stronger than ever, it seeks a master to join the battlefield, aiming for nothing but death and destruction%.$", function(n)
    return "En otro tiempo un majestuoso y orgulloso caballo de guerra, " .. N(n) .. " cayó en una terrible batalla hace muchos años. Impulsado por la agonía y el dolor, su espíritu volvió a poseer su cadáver putrefacto para vengar su muerte. Más fuerte que nunca, busca un amo con el que unirse al campo de batalla, sin aspirar a nada más que muerte y destrucción."
end)

add("^Once captured and held captive by a mad hunter, the (.+) is the result of sick experiments%. Fed only with demon dust and concentrated demonic blood it had to endure a dreadful transformation%. The demonic blood that is now running through its veins, however, provides it with incredible strength and endurance%.$", function(n)
    return "Capturado en otro tiempo y retenido por un cazador loco, " .. N(n) .. " es el resultado de experimentos enfermizos. Alimentado solo con polvo de demonio y sangre demoníaca concentrada, tuvo que soportar una terrible transformación. Sin embargo, la sangre demoníaca que ahora corre por sus venas le proporciona una fuerza y una resistencia increíbles."
end)

add("^Get yourself a mighty travelling companion with broad shoulders and a gentle heart%. (.+) is a physically imposing creature that is much more peaceful than its relatives, Tiquanda's wild kongras, and will carry you safely wherever you ask it to go%.$", function(n)
    return "Hazte con un poderoso compañero de viaje de anchos hombros y corazón noble. " .. N(n) .. " es una criatura físicamente imponente, mucho más pacífica que sus parientes, los kongras salvajes de Tiquanda, y te llevará con seguridad adonde se lo pidas."
end)

add("^If you are looking for a vigilant and faithful companion, look no further! Glide through every realm and stare into the darkest abyss on the back of an? (.+)%. They already know everything about you anyway for they have been watching you from the shadows!$", function(n)
    return "Si buscas un compañero vigilante y fiel, ¡no busques más! Surca todos los reinos y contempla el abismo más oscuro a lomos de " .. N(n) .. ". De todos modos ya lo saben todo sobre ti, ¡porque te han estado observando desde las sombras!"
end)

add("^The (.+) is a scorpion that has surpassed the natural boundaries of its own kind%. Way bigger, stronger and faster than ordinary scorpions, it makes a perfect companion for fearless heroes and explorers%. Just be careful of his poisonous sting when you mount it%.$", function(n)
    return N(n) .. " es un escorpión que ha superado los límites naturales de su especie. Mucho más grande, fuerte y rápido que los escorpiones comunes, es el compañero perfecto para héroes y exploradores intrépidos. Solo ten cuidado con su aguijón venenoso al montarlo."
end)

add("^The (.+) has external characteristics of different breeds%. It is assumed that his brain is also composed of many different species, which makes it completely unpredictable%. Only few have managed to approach this creature unharmed and only the best could tame it%.$", function(n)
    return N(n) .. " tiene rasgos externos de distintas razas. Se supone que su cerebro también está compuesto por muchas especies diferentes, lo que lo hace completamente impredecible. Muy pocos han logrado acercarse a esta criatura ilesos y solo los mejores pudieron domarla."
end)

add("^If the (.+) moves its fins, it generates enough air pressure that it can even float over land%. Its numerous eyes allow it to quickly detect dangers even in confusing situations and eliminate them with one powerful bite%. If you watch your fingers, you are going to be good friends%.$", function(n)
    return "Si " .. N(n) .. " mueve sus aletas, genera tanta presión de aire que incluso puede flotar sobre la tierra. Sus numerosos ojos le permiten detectar rápidamente peligros incluso en situaciones confusas y eliminarlos de un solo mordisco. Si cuidas tus dedos, seréis buenos amigos."
end)

add("^Your lower back worsens with every trip you spend on the back of your mount and you are looking for a more comfortable alternative to travel through the lands%? Say no more! The (.+) comes with two top%-performing hares that never get tired thanks to the brand new and highly innovative propulsion technology%. Just keep some back%-up carrots in your pocket and you will be fine!$", function(n)
    return "¿Te duele más la espalda con cada viaje a lomos de tu montura y buscas una alternativa más cómoda para recorrer las tierras? ¡No busques más! El " .. N(n) .. " viene con dos liebres de alto rendimiento que nunca se cansan gracias a su novísima e innovadora tecnología de propulsión. Solo lleva unas zanahorias de repuesto en el bolsillo y todo irá bien."
end)

add("^You are intrigued by tortoises and would love to throne on a tortoise shell when travelling the Tibian wilderness%? The (.+) might become your new trustworthy companion then, which will transport you safely and even carry you during combat%.$", function(n)
    return "¿Te intrigan las tortugas y te encantaría reinar sobre un caparazón al recorrer los parajes de Tibia? Entonces " .. N(n) .. " podría ser tu nuevo y fiable compañero, que te transportará con seguridad e incluso te llevará en combate."
end)

add("^Its roaring is piercing marrow and bone and can be heard over ten miles away%. The (.+) is the undisputed ruler of its territory and no one messes with this animal%. Show no fear and prove yourself worthy of its trust and you will get yourself a valuable companion for your adventures%.$", function(n)
    return "Su rugido atraviesa hasta la médula y los huesos y se oye a más de diez millas. El " .. N(n) .. " es el amo indiscutible de su territorio y nadie se mete con este animal. No muestres miedo y demuestra que eres digno de su confianza para conseguir un valioso compañero para tus aventuras."
end)

add("^If you are more interested in the achievements of science, you may enjoy a ride on the (.+), one of the new insect%-like flying machines%. Even if you do not move around, the wings of these unusual vehicles are always in motion%.$", function(n)
    return "Si te interesan más los logros de la ciencia, quizá disfrutes de un paseo en " .. N(n) .. ", una de las nuevas máquinas voladoras con forma de insecto. Aunque no te muevas, las alas de estos insólitos vehículos están siempre en movimiento."
end)

add("^Do you like fluffy bunnies but think they are too small%? Do you admire the majesty of stags and their antlers but are afraid of their untameable wilderness%? Do not worry, the mystic creature (.+) consolidates the best qualities of both animals%. Hop on its backs and enjoy the ride%.$", function(n)
    return "¿Te gustan los conejitos peludos pero te parecen demasiado pequeños? ¿Admiras la majestuosidad de los ciervos y sus cuernos pero temes su salvajismo indomable? No te preocupes: la criatura mística " .. N(n) .. " reúne las mejores cualidades de ambos animales. Salta a su lomo y disfruta del paseo."
end)

-- Descripciones de monturas únicas
local bespoke = {
    ["The Armoured War Horse is a dangerous black beauty! When you see its threatening, blood-red eyes coming towards you, you'll know trouble is on its way. Protected by its heavy armour plates, the warhorse is the perfect partner for dangerous hunting sessions and excessive enemy slaughtering."] = "¡El Caballo de guerra acorazado es una peligrosa belleza negra! Cuando veas venir hacia ti sus amenazantes ojos rojo sangre, sabrás que se acercan problemas. Protegido por sus pesadas placas de armadura, el caballo de guerra es el compañero perfecto para cacerías peligrosas y para masacrar enemigos sin medida.",
    ["The Festive Mammoth, Holiday Mammoth and Merry Mammoth are gentle giants with a massive appearance and impressive tusks, whose mission it is to deliver gifts all across Tibia. They are good-natured beings, spreading joy wherever they go, but you best not cross them - a mammoth never forgets."] = "El Mamut festivo, el Mamut de vacaciones y el Mamut alegre son gigantes bondadosos de aspecto enorme y colmillos impresionantes, cuya misión es repartir regalos por toda Tibia. Son seres de buen carácter que esparcen alegría allá donde van, pero mejor no los provoques: un mamut nunca olvida.",
    ["A magical fire burns inside these wolves. Bred as the faithful guardians for an eccentric wizard's tower, these creatures make for loyal companions during your travels. While not originally intended for riding, their sturdy frame makes the Dawn Strayer, Dusk Pryer and Snow Strider suitable mounts."] = "Un fuego mágico arde dentro de estos lobos. Criados como fieles guardianes de la torre de un mago excéntrico, estas criaturas son compañeras leales durante tus viajes. Aunque no estaban pensados para montarlos, su robusta constitución hace del Errante del alba, el Fisgón del crepúsculo y el Caminante de la nieve monturas adecuadas.",
    ["The Bogwurm, Gloomwurm, and Rustwurm belong to a little known subset of the dragon family, and usually live out their lives in habitats far away from human interaction. Them being cunning hunters, and their keen sense of perception make these wurms great companions for whomever can locate and tame them."] = "El Wurm del pantano, el Wurm sombrío y el Wurm oxidado pertenecen a un grupo poco conocido de la familia de los dragones y suelen vivir en hábitats alejados de cualquier contacto humano. Su astucia como cazadores y su aguda percepción los convierten en grandes compañeros para quien logre encontrarlos y domarlos.",
    ["Born from the depths of the forest, where flora and fauna intertwine in mysterious ways, the Floral Beast is a colourful creature that is sure to turn some heads. The Hyacinth, Peony, and Dandelion mount are loyal companions that will safely carry you through their natural habitat of the woods, or lands unknown to them."] = "Nacida de lo más profundo del bosque, donde flora y fauna se entrelazan de formas misteriosas, la Bestia floral es una criatura colorida que seguro llama la atención. Las monturas Jacinto, Peonía y Diente de león son compañeras leales que te llevarán con seguridad por su hábitat natural, el bosque, o por tierras que no conocen.",
    ["Legend has it that a mare and a stallion once reached the end of a rainbow and decided to stay there. Influenced by the mystical power of the rainbow, the mare gave birth to an exceptional foal: Not only the big, strong horn on its forehead but the unusual colouring of its hair makes the Prismatic Unicorn a unique mount in every respect."] = "Cuenta la leyenda que una yegua y un semental llegaron una vez al final de un arcoíris y decidieron quedarse allí. Influida por el poder místico del arcoíris, la yegua dio a luz a un potro excepcional: no solo el gran y fuerte cuerno de su frente, sino también el inusual color de su pelaje hacen del Unicornio prismático una montura única en todos los sentidos.",
    ["The Arctic Unicorn lives in a deep rivalry with its cousin the Blazing Unicorn. Even though they were born in completely different areas, they somehow share the same bloodline. The eternal battle between fire and ice continues. Who will win? Tangerine vs.crystal blue! The choice is yours!"] = "El Unicornio ártico vive en una profunda rivalidad con su primo, el Unicornio llameante. Aunque nacieron en regiones completamente distintas, de algún modo comparten la misma sangre. La eterna batalla entre el fuego y el hielo continúa. ¿Quién ganará? ¡Mandarina contra azul cristalino! ¡Tú eliges!",
    ["The Blazing Unicorn lives in a deep rivalry with its cousin the Arctic Unicorn. Even though they were born in completely different areas, they somehow share the same bloodline. The eternal battle between fire and ice continues. Who will win? Crystal blue vs. tangerine! The choice is yours!"] = "El Unicornio llameante vive en una profunda rivalidad con su primo, el Unicornio ártico. Aunque nacieron en regiones completamente distintas, de algún modo comparten la misma sangre. La eterna batalla entre el fuego y el hielo continúa. ¿Quién ganará? ¡Azul cristalino contra mandarina! ¡Tú eliges!",
    ["Tenacity, strength and loyalty are the hallmarks of a Frostbringer, a Winterstride or an Icebreacher. Those travelling through barren lands, pursuing goals in forbidding environments, or simply wanting a comrade for a lifetime should fall back on this stalwart companion."] = "Tenacidad, fuerza y lealtad son las señas de identidad de un Portador de escarcha, un Paso invernal o un Rompehielos. Quienes recorren tierras yermas, persiguen metas en entornos hostiles o simplemente desean un camarada para toda la vida deberían recurrir a este firme compañero.",
    ["Forged by only the highest skilled blacksmiths in the depths of Kazordoon's furnaces, a wild animal made out of the finest steel arose from glowing embers and blazing heat. Protected by its impenetrable armour, the Steelbeak is ready to accompany its master on every battleground."] = "Forjado por los herreros más hábiles en lo profundo de las fraguas de Kazordoon, un animal salvaje hecho del mejor acero surgió de brasas incandescentes y un calor abrasador. Protegido por su armadura impenetrable, el Pico de acero está listo para acompañar a su amo en cualquier campo de batalla.",
    ["Have you ever dreamed of gliding through the air on the back of a winged creature? With its deep red wings, the majestic Crimson Ray is a worthy mount for courageous heroes. Feel like a king on its back as you ride into your next adventure."] = "¿Has soñado alguna vez con planear por el aire a lomos de una criatura alada? Con sus alas de un rojo intenso, la majestuosa Raya carmesí es una montura digna de héroes valientes. Siéntete como un rey sobre su lomo mientras cabalgas hacia tu próxima aventura.",
    ["Born from the buzzing chaos of nature's most untamed corners, the Night Locust, Leaf Locust, and Pearl Locust are said to be harbingers of fortune for their allies and heralds of despair for their foes. With their vibrant wings and shimmering shells, these eerie yet majestic creatures are exceptional mounts for adventurers who thrive in the wilds."] = "Nacidas del caos zumbante de los rincones más indómitos de la naturaleza, se dice que la Langosta nocturna, la Langosta de hoja y la Langosta perlada son presagios de fortuna para sus aliados y heraldos de desesperación para sus enemigos. Con sus vibrantes alas y sus relucientes caparazones, estas criaturas inquietantes pero majestuosas son monturas excepcionales para aventureros que prosperan en la naturaleza salvaje.",
    ["High above the clouds far away from dry land, the training of giant eagles takes place. Only the cream of the crop is able to survive in such harsh environment long enough to call themselves Jousting Eagles while the weaklings find themselves at the bottom of the sea. The tough ones become noble and graceful mounts that are well known for their agility and endurance."] = "Muy por encima de las nubes, lejos de tierra firme, se entrenan las águilas gigantes. Solo los mejores logran sobrevivir en un entorno tan duro el tiempo suficiente para llamarse Águilas de justa, mientras que los débiles terminan en el fondo del mar. Los más duros se convierten en monturas nobles y elegantes, famosas por su agilidad y resistencia.",
    ["These birds have a strong maternal instinct since their fledglings are completely dependent on their parents for protection. Do not expect them to abandon their brood only because they are carrying you around. In fact, if you were to separate them from their chick, the Savanna Ostrich, Coral Rhea and Eventide Nandu would turn into vicious beings, so don't even try it!"] = "Estas aves tienen un fuerte instinto maternal, ya que sus polluelos dependen por completo de sus padres para protegerse. No esperes que abandonen a su cría solo porque te lleven a cuestas. De hecho, si las separaras de su pollito, el Avestruz de sabana, el Ñandú de coral y el Ñandú del ocaso se volverían seres feroces, ¡así que ni lo intentes!",
    ["To the keen observer, the crocovile is clearly a relative of the crocodile, albeit their look suggests an even more aggressive nature. While it is true that the power of its massive and muscular body can not only crush enemies dead but also break through any gate like a battering ram, a crocovile is, above all, a steadfast companion showing unwavering loyalty to its owner."] = "Para el observador atento, el crocovil es claramente un pariente del cocodrilo, aunque su aspecto sugiere una naturaleza aún más agresiva. Si bien su enorme y musculoso cuerpo no solo puede aplastar enemigos, sino también derribar cualquier puerta como un ariete, un crocovil es, ante todo, un compañero firme y de lealtad inquebrantable hacia su dueño.",
    ["These creatures are Floating Savants whose mind has been warped and bent to focus their extraordinary mental capabilities on one single goal: to do their master's bidding. Instead of being filled with an endless pursuit of knowledge, their live is now one of continuous thralldom and serfhood. The Floating Sage, the Floating Scholar and the Floating Augur are at your disposal."] = "Estas criaturas son Sabios flotantes cuya mente ha sido retorcida para concentrar sus extraordinarias capacidades mentales en una sola meta: cumplir las órdenes de su amo. En lugar de una búsqueda interminable de conocimiento, su vida es ahora de continua servidumbre. El Sabio flotante, el Erudito flotante y el Augur flotante están a tu disposición.",
    ["Badgers have been a staple of the Tibian fauna for a long time, and finally some daring souls have braved the challenge to tame some exceptional specimens - and succeeded! While the common badger you can encounter during your travels might seem like a rather unassuming creature, the Battle Badger, the Ether Badger, and the Zaoan Badger are fierce and mighty beasts, which are at your beck and call."] = "Los tejones llevan mucho tiempo formando parte de la fauna de Tibia, y por fin algunas almas audaces han afrontado el reto de domar ejemplares excepcionales, ¡y lo han logrado! Aunque el tejón común que puedes encontrar en tus viajes parezca una criatura bastante discreta, el Tejón de batalla, el Tejón etéreo y el Tejón zaoano son bestias feroces y poderosas que acuden a tu llamada.",
    ["The vibrant colours and elegance of a Tangerine Flecked Koi, a Brass Speckled Koi, and an Ink Spotted Koi make them a fascinating sight to behold, and their boisterous nature and speed will make you the first to arrive wherever there are riches to gain. Wield your weapon as gracefully and effortlessly as your swimming companion glides through the water, and the two of you will make the perfect and most deadly pair."] = "Los colores vibrantes y la elegancia de un Koi moteado mandarina, un Koi moteado de latón y un Koi manchado de tinta los hacen fascinantes de contemplar, y su carácter bullicioso y su velocidad te harán llegar el primero allí donde haya riquezas que ganar. Maneja tu arma con la misma gracia y soltura con que tu compañero nada por el agua, y seréis la pareja perfecta y más letal.",
    ["A seasoned warrior knows how to make an entry, and so does his faithful companion: Fully armored! Saddle up your impressive Jousting Horse to charge into battle in style, gallop into the arena on the back of your striking Tourney Horse, and ride your distinguished Parade Horse through the streets of Thais to show off your chivalrous qualities. With a horse in full barding, nobody will ever rain on your parade again."] = "Un guerrero veterano sabe cómo hacer una entrada, y su fiel compañero también: ¡totalmente acorazado! Ensilla a tu impresionante Caballo de justa para cargar a la batalla con estilo, galopa por la arena a lomos de tu llamativo Caballo de torneo y pasea a tu distinguido Caballo de desfile por las calles de Thais para lucir tus cualidades caballerescas. Con un caballo con barda completa, nadie volverá a aguarte la fiesta.",
    ["No mountain is too high, no wall too steep to climb for the agile Poppy, Mint and Cinnamon Ibex. They keep their balance on the thinnest of ledges, so you will never stumble, slip or go flying off the edges. Moreover, these sturdy fellows certainly know how to make an entrance as they dive down from the highest peaks and attack opponents with their impressive horns. And if you dare to call them a wild goat, they might kick you with their legs."] = "Ninguna montaña es demasiado alta ni ninguna pared demasiado empinada para el ágil Íbice amapola, menta y canela. Mantienen el equilibrio en las cornisas más estrechas, así que nunca tropezarás, resbalarás ni saldrás volando por el borde. Además, estos robustos compañeros saben hacer una entrada espectacular al lanzarse desde las cumbres más altas y embestir a sus rivales con sus impresionantes cuernos. Y si te atreves a llamarlos cabra montés, quizá te den una coz.",
    ["The origins of the Emerald Raven, Mystic Raven, and Radiant Raven are shrouded in darkness, as no written record nor tale told by even the most knowing storytellers mentions but a trace of them. Superstition surrounds them, as some see these gigantic birds as an echo of a long forgotten past, while others believe them to herald hitherto unknown events. What is clear is that they are highly intelligent beings which make great companions if they deem somebody worthy."] = "Los orígenes del Cuervo esmeralda, el Cuervo místico y el Cuervo radiante están envueltos en tinieblas, pues ningún registro escrito ni relato de los narradores más sabios los menciona más que de pasada. La superstición los rodea: algunos ven en estas aves gigantescas un eco de un pasado olvidado, mientras que otros creen que anuncian acontecimientos hasta ahora desconocidos. Lo que está claro es que son seres muy inteligentes y excelentes compañeros si consideran a alguien digno.",
}

for k, v in pairs(bespoke) do
    if v then ES.lines[k] = v end
end
